;
const TOPIC_ORDER = [...new Set(QUESTIONS.map(q => q.topic))];

const TIMER_START_SECONDS = 25 * 60; // ~25 minutes \u2014 51 questions is a longer paper than Bio/Chem
const STORAGE_KEY = 'gcse2med_physics_assessment_v3';

// =====================================================================
// GCSE2MED diagnostic runtime v3 (shared by the maths, chemistry, biology and physics pages)
// =====================================================================
const CFG = {"subject": "Physics", "key": "answer", "hasCourse": true, "blueprints": {"separate": [["Energy", ["Easy", "Easy", "Medium", "Medium", "Medium", "Hard"]], ["Electricity", ["Easy", "Easy", "Medium", "Medium", "Medium", "Hard", "Hard"]], ["Particle Model", ["Easy", "Easy", "Medium", "Medium", "Hard"]], ["Atomic Structure", ["Easy", "Easy", "Medium", "Medium", "Medium", "Hard"]], ["Forces", ["Easy", "Easy", "Medium", "Medium", "Medium", "Medium", "Hard", "Hard", "Hard"]], ["Waves", ["Easy", "Easy", "Medium", "Medium", "Medium", "Hard", "Hard"]], ["Magnetism", ["Easy", "Easy", "Medium", "Medium", "Hard", "Hard"]], ["Space Physics", ["Easy", "Medium", "Medium", "Medium", "Hard"]]], "combined": [["Energy", ["Easy", "Easy", "Medium", "Medium", "Medium", "Hard", "Hard"]], ["Electricity", ["Easy", "Easy", "Easy", "Medium", "Medium", "Medium", "Hard", "Hard"]], ["Particle Model", ["Easy", "Easy", "Medium", "Medium", "Medium", "Hard"]], ["Atomic Structure", ["Easy", "Easy", "Easy", "Medium", "Medium", "Medium", "Hard"]], ["Forces", ["Easy", "Easy", "Easy", "Medium", "Medium", "Medium", "Medium", "Hard", "Hard", "Hard"]], ["Waves", ["Easy", "Easy", "Medium", "Medium", "Medium", "Hard", "Hard"]], ["Magnetism", ["Easy", "Easy", "Medium", "Medium", "Hard", "Hard"]]]}, "seenKey": "gcse2med_phys_seen_v1", "lead": "{n} questions across the GCSE Physics topics on your course, picked at random from a bank of over 100 — so every attempt is a different test. You’ll have around {mins} minutes on the clock, and a wrong answer here is useful: it’s exactly what we’re looking for.", "kitNote": "", "timerFoundation": null};
const SEEN_KEY = CFG.seenKey;
const LAST_KEY = STORAGE_KEY + '_last';      // the most recent finished result, kept until the next one
const LOCK_KEY = STORAGE_KEY + '_lock';      // which browser tab is allowed to save progress
const TAB_ID = Math.random().toString(36).slice(2) + Date.now().toString(36);
const QTYPES = ['mcq', 'truefalse', 'multiselect', 'numeric'];
const qType = q => (QTYPES.includes(q.type) ? q.type : 'mcq');
const qSkill = q => q.skill || q.type;
const qAns = q => q[CFG.key];
const qDiagram = q => q.svg || q.diagram || '';
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// ---------- Each student gets a different test ----------
// Every test keeps the same shape: the same topics in the same order, and inside each topic the
// slots run easy -> medium -> harder. Foundation students get one harder slot per topic, filled
// with harder Foundation questions. Higher students get two harder slots per topic (the last
// medium slot is upgraded), filled from the stretch pool: Higher-only questions plus grade 7-9
// 'stretch' questions. 'Not sure' gets one of each, so it sits between the two. No two questions
// in a topic test the same idea, and questions this device has seen least recently are used first.
const BLUEPRINTS = CFG.blueprints;   // {separate, combined} for the sciences, {all} for maths
function blueprintFor(tier, course) {
  const base = BLUEPRINTS.all || (course === 'separate' ? BLUEPRINTS.separate : BLUEPRINTS.combined);
  if (tier === 'foundation') return base;
  return base.map(([topic, levels]) => {
    const l = levels.slice();
    const hards = l.filter(x => x === 'Hard').length;
    const k = l.lastIndexOf('Medium');
    if (k !== -1 && (hards === 0 || l.length >= 4)) l[k] = 'Hard';
    return [topic, l];
  });
}
const BLUEPRINT = blueprintFor('foundation', 'combined');
function loadSeen() {
  try { const s = JSON.parse(localStorage.getItem(SEEN_KEY) || '[]'); return Array.isArray(s) ? s : []; }
  catch (e) { return []; }
}
function saveSeen(ids) {
  try { localStorage.setItem(SEEN_KEY, JSON.stringify(ids.slice(-600))); } catch (e) {}
}
function shuffled(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}
const isStretch = q => q.level === 'Hard' && (q.tier === 'Higher' || q.stretch === true);
function buildTest(tier, course) {
  const separate = !BLUEPRINTS.all && course === 'separate';
  const onCourse = q => BLUEPRINTS.all || separate || !q.sep;
  const bp = blueprintFor(tier, course);
  const seenList = loadSeen();
  const rank = new Map(seenList.map((id, k) => [id, k]));    // higher rank = seen more recently
  const picked = [];
  bp.forEach(([topic, levels]) => {
    const usedConcepts = new Set();
    let hardSlot = 0;
    const nHard = levels.filter(x => x === 'Hard').length;
    levels.forEach(level => {
      const base = QUESTIONS.map((q, i) => ({q, i})).filter(x =>
        x.q.topic === topic && x.q.level === level && onCourse(x.q) && !picked.includes(x.i));
      const stretchPool = base.filter(x => isStretch(x.q));
      const plainPool = base.filter(x => x.q.tier === 'Foundation' && !x.q.stretch);
      let pool;
      if (level !== 'Hard') pool = plainPool;
      else {
        let wantStretch = tier === 'higher';
        if (tier === 'all') wantStretch = nHard >= 2 ? hardSlot === nHard - 1 : Math.random() < 0.5;
        if (tier === 'foundation') wantStretch = false;
        pool = wantStretch ? stretchPool : plainPool;
        if (!pool.length) pool = wantStretch ? plainPool : stretchPool.filter(x => x.q.tier !== 'Higher');
        hardSlot++;
      }
      const fresh = pool.filter(x => !usedConcepts.has(x.q.concept));
      if (fresh.length) pool = fresh;
      const unseen = pool.filter(x => !rank.has(x.i));
      let choice;
      if (unseen.length) choice = shuffled(unseen)[0];
      else if (pool.length) {
        const oldest = Math.min(...pool.map(x => rank.get(x.i)));
        choice = pool.find(x => rank.get(x.i) === oldest);
      }
      if (choice) { picked.push(choice.i); usedConcepts.add(choice.q.concept); }
    });
  });
  saveSeen(seenList.filter(i => !picked.includes(i)).concat(picked));
  return picked;
}

// Options are shuffled once per test (multiple choice only), so the right answer isn't always in the
// same place. Options that are labels (Arrow P, Section Q, Student A...) stay in letter order.
const ORIGINAL_Q = JSON.parse(JSON.stringify(QUESTIONS));
function labelOrder(q) {
  const m = q.options.map(o => String(o).match(/^(?:([A-Za-z]+)\s+)?([A-Z])$/));
  if (!m.every(Boolean) || new Set(m.map(x => x[1] || '')).size !== 1) return null;
  return q.options.map((_, k) => k).sort((a, b) => m[a][2].localeCompare(m[b][2]));
}
function makePerms(ids) {
  const p = {};
  ids.forEach(i => {
    const q = ORIGINAL_Q[i];
    if (qType(q) !== 'mcq') return;
    p[i] = labelOrder(q) || shuffled(q.options.map((_, k) => k));
  });
  return p;
}
function applyPerms(p) {
  ORIGINAL_Q.forEach((oq, i) => {
    if (qType(oq) !== 'mcq') return;
    const order = p && p[i];
    QUESTIONS[i].options = order ? order.map(k => oq.options[k]) : oq.options.slice();
    QUESTIONS[i][CFG.key] = order ? order.indexOf(oq[CFG.key]) : oq[CFG.key];
  });
}
function currentPerms() {
  return state.retryMode && state.practicePerm ? Object.assign({}, state.perm || {}, state.practicePerm) : (state.perm || {});
}

// ---------- State ----------
function freshState(keep) {
  return {
    v: 3,
    screen: 'intro',
    current: 0,
    answers: [],
    locked: [],
    timeRemaining: TIMER_START_SECONDS,
    elapsed: 0,
    tier: (keep && keep.tier) || 'all',
    course: (keep && keep.course) || 'unsure',
    timerMsgShown: false,
    activeIndexes: [],
    retryMode: false,
    mainAnswers: null,
    mainActiveIndexes: null,
    expandedTopics: [],
    showAllWrong: false,
    perm: null,
    practicePerm: null,
    startedAt: null,
    completedAt: null,
  };
}
let state = freshState();
let timerInterval = null;
let blocked = false;          // true when another tab has taken over this assessment
let lastLockTime = 0;         // guards against a double Enter skipping the feedback

function readJSON(key) { try { const r = localStorage.getItem(key); return r ? JSON.parse(r) : null; } catch (e) { return null; } }
function writeJSON(key, v) { try { localStorage.setItem(key, JSON.stringify(v)); return true; } catch (e) { return false; } }
function claimLock() { writeJSON(LOCK_KEY, { id: TAB_ID, t: Date.now() }); blocked = false; }
function ownsLock() { const l = readJSON(LOCK_KEY); return !l || l.id === TAB_ID; }
function saveState() {
  if (state.screen === 'intro') return;
  if (!ownsLock()) { if (state.screen === 'quiz') enterBlocked(); return; }
  writeJSON(STORAGE_KEY, state);
}
function loadSavedState() {
  const s = readJSON(STORAGE_KEY);
  if (s && s.v === 3 && ['quiz', 'results', 'retryResults'].includes(s.screen) && Array.isArray(s.activeIndexes) && s.activeIndexes.length) return s;
  return null;
}
function clearSavedState() { try { localStorage.removeItem(STORAGE_KEY); } catch (e) {} }
function enterBlocked() {
  if (blocked) return;
  blocked = true;
  stopTimer();
  render();
}
window.addEventListener('storage', (e) => {
  if (e.key === LOCK_KEY && e.newValue) {
    try { if (JSON.parse(e.newValue).id !== TAB_ID && state.screen === 'quiz') enterBlocked(); } catch (err) {}
  }
});
function restore(saved) {
  state = Object.assign(freshState(), saved);
  applyPerms(currentPerms());
  if (state.screen === 'quiz') claimLock();
  if (state.screen === 'quiz' && !state.retryMode) startTimer();
}

function activeQuestions() { return state.activeIndexes.map(i => QUESTIONS[i]); }
function formatTime(totalSeconds) {
  const s = Math.max(0, totalSeconds);
  const m = Math.floor(s / 60), sec = s % 60;
  return `${m}:${sec < 10 ? '0' : ''}${sec}`;
}
function formatDuration(sec) {
  const m = Math.floor(sec / 60), s = sec % 60;
  return m ? `${m} min${s ? ' ' + s + ' s' : ''}` : `${s} s`;
}
function startTimer() {
  if (timerInterval) clearInterval(timerInterval);
  timerInterval = setInterval(() => {
    if (state.screen !== 'quiz' || state.retryMode || blocked) return;
    state.timeRemaining--;
    state.elapsed = (state.elapsed || 0) + 1;
    const t = document.getElementById('quiz-timer');
    if (t) {
      t.textContent = formatTime(state.timeRemaining);
      t.classList.toggle('timer-up', state.timeRemaining <= 0);
    }
    if (state.timeRemaining <= 0 && !state.timerMsgShown) {
      state.timerMsgShown = true;
      render();
    }
    saveState();
  }, 1000);
}
function stopTimer() { if (timerInterval) { clearInterval(timerInterval); timerInterval = null; } }

function el(html) {
  const t = document.createElement('template');
  t.innerHTML = html.trim();
  return t.content.firstElementChild;
}

// Two-step confirm on a button, without browser pop-ups: the first press asks, the second acts.
function confirmButton(btn, askLabel, action) {
  const original = btn.innerHTML;
  let armed = false, timer = null;
  btn.addEventListener('click', () => {
    if (!armed) {
      armed = true;
      btn.innerHTML = askLabel;
      btn.classList.add('btn-confirm');
      timer = setTimeout(() => { armed = false; btn.innerHTML = original; btn.classList.remove('btn-confirm'); }, 5000);
      return;
    }
    clearTimeout(timer);
    action();
  });
}

// ---------- Rendering ----------
let lastRenderKey = null;
let lastLockedState = false;
function render() {
  const app = document.getElementById('app');
  const key = [blocked ? 'blocked' : state.screen, state.current, state.retryMode ? 'r' : 'm', state.activeIndexes.length].join(':');
  const sameView = key === lastRenderKey;
  const nowLocked = state.screen === 'quiz' && !!state.locked[state.current];
  const justMarked = sameView && nowLocked && !lastLockedState;
  const keepY = window.scrollY;
  const active = document.activeElement;
  const focusKey = active && active.dataset ? active.dataset.fk : null;
  const hadInputFocus = active && active.classList && active.classList.contains('numeric-input');
  const caret = hadInputFocus ? active.selectionStart : null;
  app.classList.toggle('no-anim', sameView);
  app.innerHTML = '';
  if (blocked && state.screen === 'quiz') app.appendChild(renderBlocked());
  else if (state.screen === 'intro') app.appendChild(renderIntro());
  else if (state.screen === 'quiz') app.appendChild(renderQuiz());
  else if (state.screen === 'retryResults') app.appendChild(renderRetryResults());
  else app.appendChild(renderResults());
  lastRenderKey = key;
  lastLockedState = nowLocked;
  if (!sameView) {
    window.scrollTo({top: 0, behavior: 'instant'});
    if (state.screen === 'results' && !blocked) requestAnimationFrame(() => requestAnimationFrame(revealResults));
    if (state.screen === 'quiz' && !blocked) focusQuestion();
    if ((state.screen === 'results' || state.screen === 'retryResults') && !blocked) { const h = document.querySelector('#app h1'); if (h) h.focus({preventScroll: true}); }
    return;
  }
  if (focusKey) { const f = document.querySelector(`[data-fk="${focusKey}"]`); if (f) f.focus({preventScroll: true}); }
  window.scrollTo({top: keepY, behavior: 'instant'});
  if (state.screen === 'results') {
    const s = document.getElementById('score-num');
    if (s) s.textContent = s.getAttribute('data-target') + '%';
  }
  if (hadInputFocus && !nowLocked) {
    const inp = document.querySelector('.numeric-input');
    if (inp) { inp.focus({preventScroll: true}); try { inp.setSelectionRange(caret, caret); } catch (e) {} }
  }
  if (justMarked) {
    const fb = document.querySelector('.option-feedback');
    if (fb) fb.focus({preventScroll: true});
    revealFeedback();
  }
}
const finePointer = () => window.matchMedia && window.matchMedia('(hover: hover) and (pointer: fine)').matches;
function focusQuestion() {
  const inp = document.querySelector('.numeric-input:not([disabled])');
  if (inp && finePointer()) { inp.focus({preventScroll: true}); return; }
  const h = document.querySelector('.qtext');
  if (h) h.focus({preventScroll: true});
}
function revealFeedback() {
  const fb = document.querySelector('.option-feedback');
  if (!fb) return;
  const bar = document.querySelector('.quiz-actions');
  const barH = bar && getComputedStyle(bar).position === 'sticky' ? bar.offsetHeight : 0;
  const r = fb.getBoundingClientRect();
  const visibleBottom = window.innerHeight - barH - 12;
  if (r.bottom <= visibleBottom && r.top >= 0) return;
  const delta = Math.min(r.bottom - visibleBottom, r.top - 12);
  const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  window.scrollBy({top: delta, behavior: reduce ? 'instant' : 'smooth'});
}
function animateCountUp(elId, target, duration) {
  const node = document.getElementById(elId);
  if (!node) return;
  const start = performance.now();
  function tick(now) {
    const t = Math.min(1, (now - start) / duration);
    node.textContent = Math.round((1 - Math.pow(1 - t, 3)) * target) + '%';
    if (t < 1) requestAnimationFrame(tick); else node.textContent = target + '%';
  }
  requestAnimationFrame(tick);
}
function spawnConfetti(container) {
  const colours = ['#16A34A', '#2C5C8F', '#D97706'];
  for (let i = 0; i < 24; i++) {
    const piece = document.createElement('span');
    piece.style.cssText = `position:absolute;top:-10px;left:${Math.random() * 100}%;width:7px;height:11px;background:${colours[i % 3]};opacity:0.9;border-radius:1px;pointer-events:none;animation:confettiFall 1.1s ${Math.random() * 0.15}s ease-in forwards;transform:rotate(${Math.random() * 360}deg);--drift:${Math.random() * 40 - 20}px;`;
    container.appendChild(piece);
    setTimeout(() => piece.remove(), 1600);
  }
}
function revealResults() {
  const target = document.getElementById('score-num');
  if (!target) return;
  const pct = parseInt(target.getAttribute('data-target'), 10);
  if (state.completedAt && Date.now() - state.completedAt > 4000) { target.textContent = pct + '%'; return; }
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) { target.textContent = pct + '%'; return; }
  animateCountUp('score-num', pct, 800);
  if (pct >= 85) { const box = document.getElementById('report-hero-box'); if (box) spawnConfetti(box); }
}

function renderBlocked() {
  const wrap = el(`<div></div>`);
  wrap.appendChild(el(`<div class="eyebrow">Paused</div>`));
  wrap.appendChild(el(`<h2 tabindex="-1">This assessment is open somewhere else</h2>`));
  wrap.appendChild(el(`<p class="lead">You’ve opened it in another tab or window. To keep your answers safe, it can only be used in one place at a time.</p>`));
  const btn = el(`<button class="btn btn-primary">Carry on in this tab</button>`);
  btn.onclick = () => {
    const saved = loadSavedState();
    if (saved) restore(saved); else { state = freshState(state); claimLock(); }
    lastRenderKey = null;
    render();
  };
  wrap.appendChild(btn);
  wrap.appendChild(el(`<p class="small-note">Your answers from the other tab are kept. Close the other tab if you don’t need it.</p>`));
  return wrap;
}

function tierLabel(t) { return { foundation: 'Foundation tier', higher: 'Higher tier', all: 'Tier: not sure' }[t] || ''; }
function courseLabel(c) {
  if (!CFG.hasCourse) return '';
  return { combined: 'Combined Science', separate: 'Separate ' + CFG.subject, unsure: 'Course: not sure' }[c] || '';
}
function dateLabel(ms) {
  try { return new Date(ms).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }); } catch (e) { return ''; }
}
function pickerRow(label, hint, options, current, onPick, extraClass) {
  const frag = document.createDocumentFragment();
  const id = 'lbl-' + Math.random().toString(36).slice(2, 8);
  frag.appendChild(el(`<div class="tier-label" id="${id}">${label}</div>`));
  const row = el(`<div class="tier-picker ${extraClass || ''}" role="group" aria-labelledby="${id}"></div>`);
  options.forEach(([val, text]) => {
    const btn = el(`<button type="button" class="tier-btn${current === val ? ' active' : ''}" aria-pressed="${current === val}">${current === val ? '<span class="tick-mark" aria-hidden="true">✓</span>' : ''}${text}</button>`);
    btn.onclick = () => {
      onPick(val);
      row.querySelectorAll('.tier-btn').forEach(b => { b.classList.remove('active'); b.setAttribute('aria-pressed', 'false'); const t = b.querySelector('.tick-mark'); if (t) t.remove(); });
      btn.classList.add('active'); btn.setAttribute('aria-pressed', 'true');
      btn.insertAdjacentHTML('afterbegin', '<span class="tick-mark" aria-hidden="true">✓</span>');
    };
    row.appendChild(btn);
  });
  frag.appendChild(row);
  if (hint) frag.appendChild(el(`<p class="course-hint">${hint}</p>`));
  return frag;
}

function startNewTest() {
  clearSavedState();
  const ids = buildTest(state.tier, state.course);
  const keep = { tier: state.tier, course: state.course };
  state = freshState(keep);
  state.perm = makePerms(ids);
  applyPerms(state.perm);
  state.activeIndexes = ids;
  state.answers = new Array(ids.length).fill(null);
  state.locked = new Array(ids.length).fill(false);
  state.timeRemaining = (state.tier === 'foundation' && CFG.timerFoundation) ? CFG.timerFoundation : TIMER_START_SECONDS;
  state.startedAt = Date.now();
  state.screen = 'quiz';
  claimLock();
  saveState();
  startTimer();
  render();
}

function renderIntro() {
  const wrap = el(`<div></div>`);
  const saved = loadSavedState();
  const inProgress = saved && saved.screen === 'quiz' && !saved.retryMode ? saved : null;
  if (inProgress) {
    const answered = inProgress.locked.filter(Boolean).length;
    const meta = [tierLabel(inProgress.tier), courseLabel(inProgress.course)].filter(Boolean).join(' · ');
    const banner = el(`
      <div class="resume-banner" role="region" aria-label="Assessment in progress">
        <b>You have an assessment in progress</b>
        <span>You’ve answered ${answered} of ${inProgress.activeIndexes.length} questions (${meta}). Pick up where you left off, or start again.</span>
        <div class="resume-row"></div>
      </div>`);
    const resumeBtn = el(`<button class="btn btn-primary">Continue</button>`);
    resumeBtn.onclick = () => { restore(inProgress); lastRenderKey = null; render(); };
    const discardBtn = el(`<button class="btn btn-secondary">Start over</button>`);
    confirmButton(discardBtn, 'Tap again to delete your progress', () => { claimLock(); clearSavedState(); state = freshState(inProgress); render(); });
    banner.querySelector('.resume-row').appendChild(resumeBtn);
    banner.querySelector('.resume-row').appendChild(discardBtn);
    wrap.appendChild(banner);
  }
  const last = readJSON(LAST_KEY);
  if (!inProgress && last && last.v === 3 && Array.isArray(last.mainActiveIndexes)) {
    const lq = last.mainActiveIndexes.map(i => QUESTIONS[i]).filter(Boolean);
    if (lq.length === last.mainActiveIndexes.length) {
      applyPerms(last.perm || {});      // answers are stored as positions in that test's option order
      const pct = Math.round(100 * last.mainActiveIndexes.filter((qi, k) => isCorrect(QUESTIONS[qi], last.mainAnswers[k])).length / lq.length);
      applyPerms(currentPerms());
      const card = el(`<div class="last-result"><div><b>Your last result: ${pct}%</b><span>${[dateLabel(last.completedAt), tierLabel(last.tier), courseLabel(last.course)].filter(Boolean).join(' · ')}</span></div></div>`);
      const view = el(`<button class="btn btn-secondary btn-small">View it</button>`);
      view.onclick = () => { restore(Object.assign({}, last, { screen: 'results', retryMode: false })); saveState(); lastRenderKey = null; render(); };
      card.appendChild(view);
      wrap.appendChild(card);
    }
  }

  wrap.appendChild(el(`<div class="eyebrow">Step 1: Diagnose</div>`));
  wrap.appendChild(el(`<h2>Find out where you actually stand in ${CFG.subject}</h2>`));
  const nTest = BLUEPRINT.reduce((n, b) => n + b[1].length, 0);
  const mins = Math.round(TIMER_START_SECONDS / 60);
  wrap.appendChild(el(`<p class="lead">${CFG.lead.replace('{n}', nTest).replace('{mins}', mins)}</p>`));
  if (CFG.kitNote) wrap.appendChild(el(`<p class="kit-note">${CFG.kitNote}</p>`));
  const features = el(`<ul class="feature-list"></ul>`);
  ['Your score, and what it actually means', 'Feedback on every question as you go, not just at the end', 'A topic-by-topic breakdown of where the marks went', 'No account needed'].forEach(f => {
    features.appendChild(el(`<li><span class="tick" aria-hidden="true">✓</span><span>${f}</span></li>`));
  });
  wrap.appendChild(features);

  wrap.appendChild(pickerRow('Which tier are you sitting?',
    'Foundation papers go up to grade 5; Higher papers go up to grade 9 and include harder questions. Not sure? Ask your teacher, or choose Not sure for a mix of both.',
    [['foundation', 'Foundation'], ['higher', 'Higher'], ['all', 'Not sure']], state.tier, v => { state.tier = v; }));
  if (CFG.hasCourse) {
    wrap.appendChild(pickerRow('Which course are you taking?',
      `Combined (double) Science covers all three sciences for two GCSEs; separate (triple) ${CFG.subject} is a GCSE on its own. Not sure? You’ll only get content every student studies. Works for AQA, Edexcel and OCR Gateway.`,
      [['combined', 'Combined Science'], ['separate', 'Separate ' + CFG.subject], ['unsure', 'Not sure']], state.course || 'unsure', v => { state.course = v; }, 'course-picker'));
  }
  const startBtn = el(`<button class="btn btn-primary">${inProgress ? 'Start a new assessment' : 'Start assessment'}</button>`);
  if (inProgress) confirmButton(startBtn, 'Tap again — this deletes your saved progress', startNewTest);
  else startBtn.onclick = startNewTest;
  wrap.appendChild(startBtn);
  wrap.appendChild(el(`<a class="small-link" href="/assessment" rel="noopener">Changed your mind? Pick a different subject</a>`));
  return wrap;
}

const LETTERS = ['A', 'B', 'C', 'D', 'E', 'F'];
function optLetters(q) {
  const m = (q.options || []).map(o => String(o).match(/^(?:[A-Za-z]+\s+)?([A-Z])$/));
  return m.length && m.every(Boolean) ? m.map(x => x[1]) : LETTERS.slice(0, (q.options || []).length);
}
function answerText(q) {
  const u = q.unit ? ((q.unit === '°' || q.unit === '%') ? q.unit : ' ' + q.unit) : '';
  return (q.prefix || '') + (q.answerDisplay != null ? q.answerDisplay : qAns(q)) + u;
}
function renderQuiz() {
  const qs = activeQuestions();
  const i = state.current;
  const q = qs[i];
  const type = qType(q);
  const wrap = el(`<div></div>`);
  const pct = Math.round(((i + 1) / qs.length) * 100);
  const timerOrLabel = state.retryMode
    ? `<span class="timer">Practice round</span>`
    : `<span class="timer${state.timeRemaining <= 0 ? ' timer-up' : ''}" id="quiz-timer" role="timer" aria-label="Time left">${formatTime(state.timeRemaining)}</span>`;
  wrap.appendChild(el(`<div class="progress-label"><span>Question ${i + 1} of ${qs.length}</span>${timerOrLabel}</div>`));
  wrap.appendChild(el(`<div class="progress-track" role="progressbar" aria-valuemin="1" aria-valuemax="${qs.length}" aria-valuenow="${i + 1}" aria-label="Progress"><div class="progress-fill" style="width:${pct}%"></div></div>`));
  if (!state.retryMode && state.timerMsgShown && state.timeRemaining <= 0) {
    wrap.appendChild(el(`<div class="timer-msg" role="status">⏱️ Time’s up — no problem, there’s no penalty. Keep going at your own pace.</div>`));
  }
  wrap.appendChild(el(`<div class="topic-label">${q.topic}</div>`));
  wrap.appendChild(el(`<p class="qtext" role="heading" aria-level="2" tabindex="-1">${q.question}</p>`));
  if (qDiagram(q)) wrap.appendChild(el(`<div class="qdiagram q-diagram">${qDiagram(q)}</div>`));

  const locked = state.locked[i];
  const selected = state.answers[i];
  const idk = selected === 'idk';
  const ans = qAns(q);

  if (type === 'mcq' || type === 'truefalse' || type === 'multiselect') {
    const multi = type === 'multiselect';
    const picks = multi && Array.isArray(selected) ? selected : [];
    if (multi) wrap.appendChild(el(`<p class="select-all-note">Select all that apply, then press Check answer.</p>`));
    const group = el(`<div class="options" role="${multi ? 'group' : 'radiogroup'}" aria-label="Answer options"></div>`);
    const lets = optLetters(q);
    q.options.forEach((opt, idx) => {
      const isPicked = multi ? picks.includes(idx) : selected === idx;
      const isRight = multi ? ans.includes(idx) : idx === ans;
      let cls = 'option', badge = lets[idx], status = '';
      if (!locked && isPicked) cls += ' picked';
      if (locked) {
        cls += ' locked';
        if (isRight) { cls += ' correct-answer'; badge = '✓'; status = ' (correct answer)'; }
        else if (isPicked) { cls += ' wrong-answer'; badge = '✕'; status = ' (your answer, incorrect)'; }
      }
      const role = multi ? `aria-pressed="${isPicked}"` : `role="radio" aria-checked="${isPicked}"`;
      const box = multi && !locked ? `<span class="opt-box" aria-hidden="true">${isPicked ? '☑' : '☐'}</span>` : '';
      const optEl = el(`<button class="${cls}" type="button" data-fk="opt-${idx}" data-key="${lets[idx]}" ${role} ${locked ? 'aria-disabled="true"' : ''}><span class="opt-letter" aria-hidden="true">${badge}</span>${box}<span class="opt-text">${opt}</span><span class="sr-only">${status}</span></button>`);
      if (!locked) {
        optEl.onclick = () => {
          if (multi) {
            const p = Array.isArray(state.answers[i]) ? state.answers[i].slice() : [];
            const at = p.indexOf(idx);
            if (at === -1) p.push(idx); else p.splice(at, 1);
            state.answers[i] = p;
          } else {
            state.answers[i] = idx;
            state.locked[i] = true;
            lastLockTime = Date.now();
          }
          saveState();
          render();
        };
      }
      group.appendChild(optEl);
    });
    wrap.appendChild(group);
  }

  if (type === 'numeric') {
    const shown = (selected === null || selected === undefined || idk) ? '' : selected;
    const cls = locked ? (isCorrect(q, selected) ? ' correct-answer' : ' wrong-answer') : '';
    const kb = q.keyboard === 'text' ? 'text' : 'decimal';
    const inputEl = el(`<input type="text" inputmode="${kb}" enterkeyhint="done" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" class="numeric-input${cls}" aria-label="Your answer${q.unit ? ' in ' + esc(q.unit) : ''}" placeholder="${idk ? 'You chose “I don’t know”' : 'Type your answer'}" ${locked ? 'disabled' : ''}>`);
    inputEl.value = shown;
    if (!locked) {
      inputEl.oninput = (e) => {
        state.answers[i] = e.target.value;
        const btn = document.querySelector('.quiz-actions .btn-primary');
        if (btn) btn.disabled = e.target.value.trim() === '';
        saveState();
      };
    }
    inputEl.addEventListener('focus', () => { if (!finePointer()) setTimeout(() => inputEl.scrollIntoView({block: 'center', behavior: 'smooth'}), 300); });
    const row = el(`<div class="numeric-row"></div>`);
    if (q.prefix) row.appendChild(el(`<span class="unit-tag" aria-hidden="true">${q.prefix}</span>`));
    row.appendChild(inputEl);
    if (q.unit) row.appendChild(el(`<span class="unit-tag" aria-hidden="true">${q.unit}</span>`));
    wrap.appendChild(row);
    const hints = [];
    if (q.unit && q.unit !== '%' && q.unit !== '°') hints.push(`The answer is in ${q.unit} — you don’t need to type the unit.`);
    if (q.keyboard === 'text') hints.push('You can type a fraction (like 3/8) or a decimal.');
    if (hints.length && !locked) wrap.appendChild(el(`<p class="input-hint">${hints.join(' ')}</p>`));
  }

  if (!locked) {
    const idkBtn = el(`<button type="button" class="idk-btn">I don’t know this one</button>`);
    idkBtn.onclick = () => { state.answers[i] = 'idk'; state.locked[i] = true; lastLockTime = Date.now(); saveState(); render(); };
    wrap.appendChild(idkBtn);
  }

  if (locked) {
    const correct = isCorrect(q, selected);
    let extra = '';
    if (!correct && type === 'numeric') extra = ` The correct answer was <strong>${answerText(q)}</strong>.`;
    const head = correct ? 'Correct.' : (idk ? 'No problem — here’s how it works.' : 'Not quite.');
    wrap.appendChild(el(`<div class="option-feedback ${correct ? 'correct' : 'wrong'}" role="status" aria-live="polite" tabindex="-1"><strong class="fb-head">${correct ? '✓ ' : '✕ '}${head}</strong> ${q.explanation}${extra}</div>`));
  }

  const btnRow = el(`<div class="btn-row quiz-actions"></div>`);
  const backBtn = el(`<button class="btn btn-secondary">← Back</button>`);
  backBtn.disabled = (i === 0);
  backBtn.onclick = () => { if (i > 0) { state.current--; saveState(); render(); } };
  const needsSubmit = type === 'numeric' || type === 'multiselect';
  const hasAnswer = () => {
    const v = state.answers[i];
    if (v === 'idk') return true;
    if (type === 'numeric') return v !== null && v !== undefined && String(v).trim() !== '';
    if (type === 'multiselect') return Array.isArray(v) && v.length > 0;
    return v !== null && v !== undefined;
  };
  let label;
  if (needsSubmit && !locked) label = 'Check answer';
  else if (i === qs.length - 1) label = state.retryMode ? 'See how I did' : 'See my results';
  else label = 'Next →';
  const nextBtn = el(`<button class="btn btn-primary">${label}</button>`);
  nextBtn.disabled = !hasAnswer();
  nextBtn.onclick = () => {
    if (!hasAnswer()) return;
    if (needsSubmit && !locked) {
      if (type === 'numeric' && state.answers[i] !== 'idk' && isNaN(parseAnswer(state.answers[i], q)) && parseProblem !== 'unit') {
        const msg = parseProblem === 'several'
          ? 'Please give just one answer, as a single number.'
          : 'We couldn’t read that as a number. Type just the number, for example 4.5, 3/8 or 1.2 × 10^3.';
        let hint = document.querySelector('.input-error');
        if (!hint) { hint = el(`<p class="input-error" role="alert"></p>`); document.querySelector('.numeric-row').after(hint); }
        hint.textContent = msg;
        const inp = document.querySelector('.numeric-input'); if (inp) inp.focus();
        return;
      }
      state.locked[i] = true;
      lastLockTime = Date.now();
      saveState();
      render();
      return;
    }
    if (i === qs.length - 1) finishRound();
    else { state.current++; saveState(); render(); }
  };
  btnRow.appendChild(backBtn);
  btnRow.appendChild(nextBtn);
  wrap.appendChild(btnRow);

  const tip = type === 'numeric'
    ? 'Tip: type your answer and press Enter to check it.'
    : (type === 'multiselect' ? 'Tip: press A–D (or 1–4) to tick options, Enter to check.' : 'Tip: press A–D (or 1–4) to answer, Enter to continue.');
  wrap.appendChild(el(`<p class="assess-note">${state.retryMode ? 'Just the questions you got wrong — no clock, no pressure.' : 'The clock is just a rough guide, so don’t worry if you run over. It pauses if you close the page.'} <span class="kbd-tip">${tip}</span></p>`));
  return wrap;
}

function finishRound() {
  if (state.retryMode) {
    state.screen = 'retryResults';
  } else {
    state.mainAnswers = state.answers.slice();
    state.mainActiveIndexes = state.activeIndexes.slice();
    state.completedAt = Date.now();
    state.screen = 'results';
    stopTimer();
    writeJSON(LAST_KEY, state);
  }
  saveState();
  render();
}

// ---------- Marking ----------
// Typed answers: units are optional; a unit in the same family as the expected one but different
// (kg for g, mins for hours) is wrong; text the page can't read as one number is sent back to the
// student to fix instead of being marked wrong.
const UNIT_ALIASES = {
  'mins': 'min', 'minute': 'min', 'minutes': 'min', 'hrs': 'h', 'hr': 'h', 'hour': 'h', 'hours': 'h',
  'secs': 's', 'sec': 's', 'second': 's', 'seconds': 's', 'kph': 'km/h', 'kmh': 'km/h', 'kmph': 'km/h',
  'ml': 'cm3', 'millilitre': 'cm3', 'millilitres': 'cm3', 'cc': 'cm3', 'l': 'dm3', 'litre': 'dm3', 'litres': 'dm3',
  'kilogram': 'kg', 'kilograms': 'kg', 'gram': 'g', 'grams': 'g', 'milligram': 'mg', 'milligrams': 'mg',
  'metre': 'm', 'metres': 'm', 'meter': 'm', 'meters': 'm', 'centimetre': 'cm', 'centimetres': 'cm',
  'millimetre': 'mm', 'millimetres': 'mm', 'kilometre': 'km', 'kilometres': 'km', 'joule': 'j', 'joules': 'j',
  'kilojoule': 'kj', 'kilojoules': 'kj', 'watt': 'w', 'watts': 'w', 'kilowatt': 'kw', 'kilowatts': 'kw',
  'pence': 'p', 'degrees': '°', 'degree': '°', 'deg': '°', 'degc': '°c', 'm/sec': 'm/s', 'mpers': 'm/s',
};
const UNIT_FAMILIES = [
  ['mm', 'cm', 'm', 'km'], ['mg', 'g', 'kg', 'tonnes', 'tonne'], ['ms', 's', 'min', 'h'],
  ['j', 'kj', 'mj'], ['w', 'kw', 'mw'], ['m/s', 'km/h', 'mph'], ['mm2', 'cm2', 'm2', 'km2'],
  ['mm3', 'cm3', 'm3', 'dm3'], ['°c', 'k'], ['j/mol', 'kj/mol'], ['mol/dm3', 'mol/cm3', 'mol/m3'],
  ['g/cm3', 'kg/m3', 'g/dm3', 'kg/dm3', 'g/m3'], ['g/s', 'g/min', 'kg/s'], ['cm3/s', 'cm3/min', 'dm3/s', 'm3/s'],
];
